// RSS/Atom을 직접 읽어 기사로 바꾸고, 기간 필터·중복 제거·한도를 적용합니다.
// 기사 1건 = 출력 1개 (다음 노드에서 링크를 하나씩 확인)
const feeds = $('설정').all().map((i) => i.json);
const cfg = feeds[0].config;
const now = Date.now();
const DAY = 24 * 60 * 60 * 1000;

// ── XML 읽기 도우미 ──
function decode(s) {
  if (s == null) return '';
  const str = String(s);
  const cdata = str.match(/^\s*<!\[CDATA\[([\s\S]*?)\]\]>\s*$/);
  if (cdata) return cdata[1].trim();
  return str
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
    .replace(/&#39;|&apos;/g, "'")
    .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&amp;/g, '&')
    .trim();
}
function tag(block, names) {
  for (const name of names) {
    const m = block.match(new RegExp(`<${name}(?:\\s[^>]*)?>([\\s\\S]*?)</${name}>`, 'i'));
    if (m && m[1].trim()) return decode(m[1]);
  }
  return '';
}
function attr(tagText, name) {
  const m = tagText.match(new RegExp(`\\s${name}\\s*=\\s*(["'])([\\s\\S]*?)\\1`, 'i'));
  return m ? decode(m[2]) : '';
}
function linkOf(block) {
  // Atom: <link rel="alternate" href="..."/> 우선, 다음은 rel 없는 link
  const links = block.match(/<link\b[^>]*\/?>/gi) || [];
  let fallback = '';
  for (const l of links) {
    const href = attr(l, 'href');
    if (!href) continue;
    const rel = attr(l, 'rel').toLowerCase();
    if (rel === 'alternate') return href;
    if (!rel && !fallback) fallback = href;
  }
  if (fallback) return fallback;
  // RSS: <link>주소</link>
  const rss = tag(block, ['link']);
  if (rss) return rss;
  // 마지막 수단: 고유 링크로 표시된 guid
  const g = block.match(/<guid\b([^>]*)>([\s\S]*?)<\/guid>/i);
  if (g && !/isPermaLink\s*=\s*["']false/i.test(g[1])) return decode(g[2]);
  return '';
}
function parseFeed(xml) {
  const blocks = xml.match(/<item[\s>][\s\S]*?<\/item>/gi) || xml.match(/<entry[\s>][\s\S]*?<\/entry>/gi) || [];
  return blocks.map((b) => ({
    title: tag(b, ['title']),
    link: linkOf(b),
    date: tag(b, ['pubDate', 'published', 'dc:date', 'updated']),
    text: tag(b, ['description', 'summary', 'content:encoded', 'content']),
  }));
}

// n8n 코드 실행 환경에는 URL 객체가 없을 수 있어 문자열로 처리합니다.
// 링크는 원문 그대로 씁니다 (상대 주소만 절대 주소로). http(s)가 아니면 버립니다.
function originOf(u) {
  const m = String(u).match(/^(https?:\/\/[^\/?#\s]+)/i);
  return m ? m[1] : '';
}
function articleUrl(link, base) {
  let s = String(link || '').trim().replace(/\s/g, '%20');
  if (!s) return null;
  if (s.startsWith('//')) s = 'https:' + s;
  else if (s.startsWith('/')) s = originOf(base) + s;
  if (!/^https?:\/\/[^\/?#\s]+\.[^\/?#\s]+/i.test(s)) return null;
  return s;
}
// 중복 비교용 키 (링크 자체는 바꾸지 않음)
function dedupeKey(href) {
  let [rest] = href.replace(/^https?:\/\//i, '').replace(/^www\./i, '').split('#');
  let [path, query = ''] = rest.split('?');
  query = query.split('&').filter((kv) => kv && !/^utm_/i.test(kv)).join('&');
  return (path.replace(/\/$/, '') + (query ? '?' + query : '')).toLowerCase();
}
const stripHtml = (s) => decode(String(s || '').replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ')).replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();

// ── 피드별 처리 ──
const seen = new Set();
const report = [];
let list = [];

$input.all().forEach((item, n) => {
  const p = item.pairedItem;
  const idx = (Array.isArray(p) ? p[0]?.item : typeof p === 'number' ? p : p?.item) ?? n;
  const feed = feeds[idx];
  if (!feed) return;

  const j = item.json;
  const status = Number(j.statusCode) || 0;
  const body = typeof j.body === 'string' ? j.body : typeof j.data === 'string' ? j.data : '';
  if (j.error || status >= 400 || !body) {
    report.push(`${feed.source}: 실패(${status || String(j.error?.message || '응답 없음').slice(0, 40)})`);
    return;
  }

  const entries = parseFeed(body);
  const days = feed.category === 'ai' ? cfg.aiDays : cfg.worldDays;
  let kept = 0, badLink = 0, badDate = 0, old = 0, dup = 0;
  for (const e of entries) {
    const url = articleUrl(e.link, feed.url);
    if (!url) { badLink++; continue; }
    const key = dedupeKey(url);
    if (seen.has(key)) { dup++; continue; }
    const time = new Date(e.date).getTime();
    if (!time || Number.isNaN(time)) { badDate++; continue; }
    if (now - time > days * DAY || time - now > DAY) { old++; continue; }

    seen.add(key);
    kept++;
    const raw = stripHtml(e.text);
    const hn = raw.match(/Points:\s*(\d+)/i);
    list.push({
      category: feed.category,
      source: feed.source,
      trust: feed.trust,
      title: stripHtml(e.title),
      url,
      publishedAt: new Date(time).toISOString(),
      snippet: raw.slice(0, 400),
      hnPoints: hn ? Number(hn[1]) : 0,
    });
  }
  report.push(`${feed.source}: ${entries.length}건 중 ${kept}건 사용 (링크 오류 ${badLink}, 날짜 오류 ${badDate}, 기간 밖 ${old}, 중복 ${dup})`);
});

// 매체당 최대 N건 (최신순), 전체 최대 M건
const perSource = new Map();
list.sort((a, b) => b.publishedAt.localeCompare(a.publishedAt));
list = list.filter((c) => {
  const n = perSource.get(c.source) || 0;
  if (n >= cfg.maxPerSource) return false;
  perSource.set(c.source, n + 1);
  return true;
}).slice(0, cfg.maxTotal);

if (list.length === 0) {
  throw new Error(`수집된 기사가 없습니다. 입력 ${$input.all().length}건. 피드별 결과: ${report.join(' / ') || '없음'}`);
}

return list.map((a) => ({ json: a }));

// 링크 확인 결과로 열리지 않는 기사를 빼고 Gemini 요청을 만듭니다.
const cfg = $('설정').first().json.config;
const listed = $('기사 정리').all().map((i) => i.json);

// 열리지 않는 링크로 판단: 404·410, 5xx(봇 차단 화면 제외), 연결 실패
// 401·403·405·429 등은 사람이 브라우저로 열면 열리는 경우가 많아 살립니다.
function isAlive(r) {
  if (!r || r.error) return false;
  const status = Number(r.statusCode);
  if (!status) return false;
  const h = r.headers || {};
  if (h['cf-mitigated'] === 'challenge') return true;
  if (status === 404 || status === 410) return false;
  if (status >= 500 && status !== 501) return false;
  return true;
}

const alive = [];
const dead = [];
$input.all().forEach((item, n) => {
  const p = item.pairedItem;
  const idx = (Array.isArray(p) ? p[0]?.item : typeof p === 'number' ? p : p?.item) ?? n;
  const a = listed[idx];
  if (!a) return;
  if (isAlive(item.json)) alive.push(a);
  else dead.push({ source: a.source, url: a.url, status: item.json.statusCode || String(item.json.error?.message || 'error').slice(0, 80) });
});

if (alive.length === 0) throw new Error('링크가 열리는 기사가 없습니다. 링크 확인 출력과 네트워크 상태를 확인하세요.');

const articles = alive.map((a, i) => ({ id: i, ...a }));

const prompt = `당신은 한국어 뉴스 편집자입니다. 아래 기사 목록(JSON Lines)을 읽고 기사마다 다음을 작성하세요.

- titleKo: 자연스러운 한국어 제목 (원문이 한국어면 그대로 다듬기)
- summary: 2~3문장 한국어 요약. 사실만, 과장 없이.
- keyPoints: 핵심 내용 2~4개 (짧은 명사형 문장)
- tags: 한국어 또는 널리 쓰는 영문 약어 태그 1~3개 (예: LLM, 에이전트, 오픈소스, 반도체, 규제, 연구, 투자, 외교, 경제, 분쟁, 기후)
- credibility: 1~5. 공식 발표·1차 출처·주요 통신사 5, 주요 언론 4, 전문 블로그·커뮤니티 3, 근거 부족·추측·루머 1~2
- impact: 0~100. 업계·사회에 미치는 영향과 화제성
- storyKey: 같은 사건을 다룬 기사끼리 같은 값을 주세요. 짧은 영문 소문자 kebab-case (예: openai-gpt-launch). 다른 사건이면 다른 값.

그리고 briefing 필드에 "오늘의 브리핑"을 Markdown으로 쓰세요. 형식은 정확히 다음과 같은 줄 3~5개입니다. 링크는 넣지 마세요.
- **키워드**: 오늘의 핵심 흐름 한 문장

모든 기사의 id를 빠짐없이 한 번씩 포함하세요. URL은 출력하지 마세요.

기사 목록:
${articles.map((a) => JSON.stringify({ id: a.id, category: a.category, source: a.source, title: a.title, publishedAt: a.publishedAt, snippet: a.snippet })).join('\n')}`;

const requestBody = {
  contents: [{ role: 'user', parts: [{ text: prompt }] }],
  generationConfig: {
    temperature: 0.3,
    maxOutputTokens: 32768,
    thinkingConfig: { thinkingBudget: 0 },
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'OBJECT',
      properties: {
        briefing: { type: 'STRING' },
        items: {
          type: 'ARRAY',
          items: {
            type: 'OBJECT',
            properties: {
              id: { type: 'INTEGER' },
              titleKo: { type: 'STRING' },
              summary: { type: 'STRING' },
              keyPoints: { type: 'ARRAY', items: { type: 'STRING' } },
              tags: { type: 'ARRAY', items: { type: 'STRING' } },
              credibility: { type: 'INTEGER' },
              impact: { type: 'INTEGER' },
              storyKey: { type: 'STRING' },
            },
            required: ['id', 'titleKo', 'summary', 'keyPoints', 'tags', 'credibility', 'impact', 'storyKey'],
          },
        },
      },
      required: ['briefing', 'items'],
    },
  },
};

return [{ json: { articles, deadLinks: dead, requestBody } }];

// Gemini 결과를 병합하고, 같은 사건을 묶고, 점수를 계산해 Markdown과 Discord 메시지를 만듭니다.
const cfg = $('설정').first().json.config;
const { articles } = $('프롬프트 생성').first().json;
const res = $input.first().json;

const text = (res.candidates?.[0]?.content?.parts || []).map((p) => p.text || '').join('');
if (!text) throw new Error('Gemini 응답이 비어 있습니다: ' + JSON.stringify(res).slice(0, 500));
let out;
try {
  out = JSON.parse(text.replace(/^```(?:json)?\s*|\s*```$/g, ''));
} catch (e) {
  throw new Error('Gemini 응답 JSON 파싱 실패 (출력이 잘렸을 수 있음, maxTotal을 줄여 보세요): ' + e.message);
}

const byId = new Map((out.items || []).map((g) => [Number(g.id), g]));
const clamp = (n, lo, hi) => Math.min(hi, Math.max(lo, n));
const now = Date.now();
const HOUR = 60 * 60 * 1000;

// 1) 기사별 결과 병합 + 신뢰도
const merged = articles.map((a) => {
  const g = byId.get(a.id) || {};
  const gCred = clamp(Number(g.credibility) || a.trust, 1, 5);
  return {
    ...a,
    titleKo: String(g.titleKo || a.title).trim(),
    summary: String(g.summary || '').trim(),
    keyPoints: Array.isArray(g.keyPoints) ? g.keyPoints.map(String).filter(Boolean).slice(0, 4) : [],
    tags: Array.isArray(g.tags) ? [...new Set(g.tags.map((t) => String(t).replace(/^#/, '').trim()).filter(Boolean))].slice(0, 3) : [],
    credibility: clamp(Math.round((gCred + a.trust) / 2), 1, 5),
    impact: clamp(Number(g.impact) || 0, 0, 100),
    storyKey: `${a.category}:${String(g.storyKey || 'id-' + a.id).toLowerCase().trim()}`,
  };
});

// 2) 같은 사건 묶기: 매체 신뢰도가 가장 높은 기사를 대표로
const groups = new Map();
for (const m of merged) {
  if (!groups.has(m.storyKey)) groups.set(m.storyKey, []);
  groups.get(m.storyKey).push(m);
}

const items = [];
for (const group of groups.values()) {
  group.sort((a, b) => b.trust - a.trust || b.credibility - a.credibility || a.publishedAt.localeCompare(b.publishedAt));
  const rep = group[0];
  const coverage = new Set(group.map((g) => g.source)).size;
  const hnPoints = Math.max(0, ...group.map((g) => g.hnPoints || 0));
  const impact = Math.max(...group.map((g) => g.impact));
  const age = now - new Date(rep.publishedAt).getTime();
  const recency = age <= 24 * HOUR ? 8 : age <= 48 * HOUR ? 4 : 0;
  const hotScore = clamp(Math.round(0.6 * impact + 6 * Math.min(coverage - 1, 4) + Math.min(hnPoints / 30, 10) + recency), 0, 100);
  items.push({
    category: rep.category,
    title: rep.title,
    titleKo: rep.titleKo,
    source: rep.source,
    url: rep.url,
    publishedAt: rep.publishedAt,
    summary: rep.summary,
    keyPoints: rep.keyPoints,
    tags: rep.tags,
    credibility: rep.credibility,
    hotScore,
    coverage,
  });
}
items.sort((a, b) => b.publishedAt.localeCompare(a.publishedAt));

// 3) KST 날짜와 시각
const kst = new Date(now + 9 * HOUR);
const date = kst.toISOString().slice(0, 10);
const generatedAt = kst.toISOString().slice(0, 19) + '+09:00';

// 4) Markdown (frontmatter의 기사 1건 = JSON 한 줄. YAML에서 그대로 읽힘)
const briefing = String(out.briefing || '').replace(/\[([^\]]+)\]\([^)]*\)/g, '$1').replace(/https?:\/\/\S+/g, '').trim() || '- **오늘의 흐름**: 브리핑을 만들지 못했습니다.';
const md = [
  '---',
  `date: "${date}"`,
  `generatedAt: "${generatedAt}"`,
  'items:',
  ...items.map((i) => '  - ' + JSON.stringify(i)),
  '---',
  '',
  briefing,
  '',
].join('\n');

// 5) Discord 메시지 (임베드 3개)
const site = String(cfg.siteUrl).replace(/\/$/, '');
const recent = (i) => now - new Date(i.publishedAt).getTime() <= 3 * 24 * HOUR;
const top = (cat, n) => items.filter((i) => i.category === cat && recent(i)).sort((a, b) => b.hotScore - a.hotScore).slice(0, n);
const cut = (s, n) => (s.length > n ? s.slice(0, n - 1) + '…' : s);
const list = (arr) => arr.length
  ? arr.map((i, k) => `**${k + 1}. [${cut(i.titleKo, 90)}](${i.url})**\n${i.source} · 인기도 ${i.hotScore}${i.coverage > 1 ? ` · ${i.coverage}개 매체` : ''}`).join('\n\n')
  : '해당 기간 기사가 없습니다.';

const discordPayload = {
  username: 'AI 뉴스 브리프',
  embeds: [
    { title: `오늘의 브리핑 (${date})`, url: site + '/', description: cut(briefing, 4000), color: 0x2f5fd0 },
    { title: 'AI Hot 5', url: site + '/hot', description: cut(list(top('ai', 5)), 4000), color: 0xe2620f },
    { title: '국제 Hot 3', url: site + '/world', description: cut(list(top('world', 3)), 4000), color: 0x0e8a8c },
  ],
};

// n8n 코드 실행 환경에 Buffer가 없을 수 있어 직접 UTF-8 → Base64로 바꿉니다.
function toBase64(str) {
  const bytes = [];
  for (const ch of str) {
    let c = ch.codePointAt(0);
    if (c < 0x80) bytes.push(c);
    else if (c < 0x800) bytes.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    else if (c < 0x10000) bytes.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    else bytes.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
  }
  const A = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  let out = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const [a, b = 0, c = 0] = [bytes[i], bytes[i + 1], bytes[i + 2]];
    const n = (a << 16) | (b << 8) | c;
    out += A[(n >> 18) & 63] + A[(n >> 12) & 63] + (i + 1 < bytes.length ? A[(n >> 6) & 63] : '=') + (i + 2 < bytes.length ? A[n & 63] : '=');
  }
  return out;
}

const path = `${String(cfg.contentDir).replace(/\/$/, '')}/${date}.md`;

return [{
  json: {
    date,
    path,
    itemCount: items.length,
    commitMessage: `news: ${date} 다이제스트 (${items.length}건)`,
    contentBase64: toBase64(md),
    discordPayload,
  },
}];
